<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\ValueObject\Accessor\UserAccessTemporalCodeRecoveryCodeAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAccessTemporalCodeRecoveryCodeAccessor trait.
 *
 * Covers null default, string/VO assignment via withRecoveryCode,
 * getRecoveryCode/recoveryCode accessors, and isRecoveryCodeChanged with/without original.
 */
class UserAccessTemporalCodeRecoveryCodeAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRecoveryCode creates a new instance with the RecoveryCode set
     * from a string value, and getRecoveryCode returns the primitive string.
     */
    public function testWithRecoveryCodeFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRecoveryCodeAccessorUnitTest();

        // Act
        $result = $holder->withRecoveryCode('hmac-sha256:p1:cypher');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('****er', $result->getRecoveryCode());
    }
    /**
     * Asserts that withrecoveryCode has access to the value object
     * from a string value, and getRecoveryCode returns the primitive string.
     */
    public function testWithRecoveryCodeFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRecoveryCodeAccessorUnitTest();

        // Act
        $result = $holder->withRecoveryCode('hmac-sha256:p1:cypher');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('****er', $result->recoveryCode()->value());
    }
    public function testChangedRecoveryCode(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRecoveryCodeAccessorUnitTest();
        $original = $holder->withRecoveryCode('hmac-sha256:p1:cypher');
        $same = $holder->withRecoveryCode('hmac-sha256:p1:cypher');
        $modified = $holder->withRecoveryCode('hmac-sha256:p1:ocyphered');

        // Act
        $unchanged = $holder->isRecoveryCodeChanged();
        $withSame = $original->isRecoveryCodeChanged($same);
        $withDiferent = $original->isRecoveryCodeChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserAccessTemporalCodeRecoveryCodeAccessorUnitTest
{
    use UserAccessTemporalCodeRecoveryCodeAccessor;
}
